import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { AuthService } from '../../core/services/auth.service';

interface AdminUser {
  id: number;
  nome: string;
  email: string;
  tipo_usuario_id: number;
  criado_em: string;
}

interface AdminUsersResponse {
  success: boolean;
  data: AdminUser[];
  total: number;
}

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.scss']
})
export class AdminComponent implements OnInit {
  isAdmin$ = this.authService.isAdmin$;
  isLoading = true;
  hasError = false;
  errorMessage = '';
  usuarios: AdminUser[] = [];

  constructor(
    private authService: AuthService,
    private router: Router,
    private http: HttpClient
  ) {}

  ngOnInit(): void {
    this.isAdmin$.subscribe((isAdmin: boolean) => {
      if (!isAdmin) {
        this.router.navigate(['/dashboard']);
        return;
      }

      this.carregarUtilizadores();
    });
  }

  carregarUtilizadores(): void {
    this.isLoading = true;
    this.hasError = false;
    this.errorMessage = '';

    this.http.get<AdminUsersResponse>('http://localhost/gfp/backend/api/admin/utilizadores').subscribe({
      next: (response) => {
        this.usuarios = Array.isArray(response.data) ? response.data : [];
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Erro ao carregar utilizadores:', error);
        this.hasError = true;
        this.errorMessage = error?.error?.message || 'Erro ao carregar utilizadores. Tente novamente.';
        this.isLoading = false;
      }
    });
  }

  formatarData(data: string): string {
    const date = new Date(data);
    return new Intl.DateTimeFormat('pt-BR', {
      dateStyle: 'medium',
      timeStyle: 'short'
    }).format(date);
  }

  getTipoUsuario(tipoUsuarioId: number): string {
    return tipoUsuarioId === 1 ? 'Administrador' : 'Utilizador';
  }
}
<div class="admin-container">
  <div *ngIf="isLoading" class="loading">
    <div class="spinner"></div>
  </div>

  <div *ngIf="!isLoading && (isAdmin$ | async)" class="admin-content">
    <div class="admin-header">
      <div>
        <h1>Gestão de Utilizadores</h1>
        <p>Apenas o administrador pode gerir os utilizadores do sistema.</p>
      </div>
      <button class="btn btn-primary" type="button" (click)="carregarUtilizadores()">Atualizar</button>
    </div>

    <div *ngIf="hasError" class="alert-error">
      <strong>Erro:</strong> {{ errorMessage }}
    </div>

    <div *ngIf="!hasError" class="admin-body">
      <div class="admin-grid">
        <div class="admin-card">
          <h3>Total de Utilizadores</h3>
          <p>{{ usuarios.length }}</p>
        </div>
      </div>

      <div *ngIf="usuarios.length > 0; else semUsuarios" class="user-table-wrapper">
        <table class="user-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Nome</th>
              <th>Email</th>
              <th>Tipo</th>
              <th>Criado em</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let usuario of usuarios">
              <td>{{ usuario.id }}</td>
              <td>{{ usuario.nome }}</td>
              <td>{{ usuario.email }}</td>
              <td>{{ getTipoUsuario(usuario.tipo_usuario_id) }}</td>
              <td>{{ formatarData(usuario.criado_em) }}</td>
            </tr>
          </tbody>
        </table>
      </div>

      <ng-template #semUsuarios>
        <div class="empty-state">
          <p>Nenhum utilizador encontrado.</p>
        </div>
      </ng-template>
    </div>
  </div>
</div>
